DELIMITER $$
--
-- Procedures
--
CREATE DEFINER=`root`@`localhost` PROCEDURE `hahaha` (IN `kebele` INT, IN `month` VARCHAR(250), IN `year` VARCHAR(250))  NO SQL
SELECT r.First_name_Amharic,r.First_name_English,r.code,r.Sequence_number,r.previ,r.Contact_number,r.Service_type,r.Gauge_number,r.Gauge_width,r.Gauge_rent,r.Kebele,r.House_number,r.frd,r.Client_status,r.pres,("") AS nextr,r.months,(r.pres-r.pres) AS nextm,r.years,(r.pres-r.pres) AS nexty,(r.pres-r.previ) AS cons,t.Max,t.block1,t.block2,t.block3,t.block4,t.block5,
IF((r.pres-r.previ)>=1 AND (r.pres-r.previ)<=3, (r.pres-r.previ)*t.block1,
   IF((r.pres-r.previ)>3 AND (r.pres-r.previ)<=10, ((r.pres-r.previ)-3)*t.block2+(3*t.block1),
      IF((r.pres-r.previ)>10 AND (r.pres-r.previ)<=15, ((r.pres-r.previ)-10)*t.block3+(3*t.block1)+(7*t.block2),
         IF((r.pres-r.previ)>15 AND (r.pres-r.previ)<=25, ((r.pres-r.previ)-15)*t.block4+(3*t.block1)+(7*t.block2)+(5*t.block3),
            IF((r.pres-r.previ)>25, ((r.pres-r.previ)-25)*t.block5+(3*t.block1)+(7*t.block2)+(5*t.block3)+(10*t.block4),'0')
         )
      )
   ) 
  )AS price,(r.Gauge_rent+IF((r.pres-r.previ)>=1 AND (r.pres-r.previ)<=3, (r.pres-r.previ)*t.block1,
   IF((r.pres-r.previ)>3 AND (r.pres-r.previ)<=10, ((r.pres-r.previ)-3)*t.block2+(3*t.block1),
      IF((r.pres-r.previ)>10 AND (r.pres-r.previ)<=15, ((r.pres-r.previ)-10)*t.block3+(3*t.block1)+(7*t.block2),
         IF((r.pres-r.previ)>15 AND (r.pres-r.previ)<=25, ((r.pres-r.previ)-15)*t.block4+(3*t.block1)+(7*t.block2)+(5*t.block3),
            IF((r.pres-r.previ)>25, ((r.pres-r.previ)-25)*t.block5+(3*t.block1)+(3*t.block2)+(5*t.block3)+(10*t.block4),'0')
         )
      )
   ) 
  )) AS total,("") AS sold_birr,("1") AS sale_status FROM clientsdurbeteview r LEFT JOIN tariff t ON r.Service_type = t.Service_type WHERE r.kebele = Kebele AND r.months=month AND r.years=year AND (r.pres-r.previ) BETWEEN t.Min AND t.Max ORDER BY r.id$$

DELIMITER ;

